/* ============================================================================
   Quiz Arena — word list for the Wend puzzle.

   Derived from the public `google-10000-english` 20k frequency list (MIT),
   filtered to plain alphabetic words of 3-8 letters and screened for anything
   that would land badly in a workplace game. Still in frequency order, which
   does two jobs at once: the first slice of each bucket is the everyday
   vocabulary Wend plants in a grid, while the whole bucket is what a traced
   word is checked against — so an unexpected but real answer is accepted
   rather than thrown out.

   Packed as one fixed-width string per length, so there are no separators to
   store and a lookup is a native indexOf on an offset multiple of the length.
   ========================================================================= */
(function () {
'use strict';
const Q = window.QA;

Q.WORDS = {
  3: '',
  4: '',
  5: '',
  6: '',
  7: '',
  8: '',
};

/* how much of each bucket is common enough to plant in a grid */
Q.WORD_COMMON = {3: 622, 4: 832, 5: 1057, 6: 1205, 7: 1212, 8: 1036};
})();
